def _lesson_html(course_title, item):
    title, idea, example, exercise = item
    return (
        f'<h2>{title}</h2><p>{idea}</p>'
        f'<h3>Разбор на примере</h3><p>{example}</p>'
        f'<h3>Практическое задание</h3><p>{exercise}</p>'
        '<h3>Самопроверка</h3><ul>'
        '<li>Объясните применённое правило своими словами.</li>'
        '<li>Проверьте результат на обычном и граничном примере.</li>'
        '<li>Запишите предположение, которое может изменить вывод.</li></ul>'
        f'<p><strong>Перенос навыка:</strong> примените приём к курсу «{course_title}» и сохраните результат в заметке.</p>'
    )


def _quiz(lesson_id, spec):
    question, options, correct, explanation = spec
    quiz_id = db().execute('INSERT INTO quizzes(lesson_id,pass_score) VALUES (?,70)', (lesson_id,)).lastrowid
    db().execute('INSERT INTO questions(quiz_id,text,options,correct,explanation) VALUES (?,?,?,?,?)',
                 (quiz_id, question, json.dumps(options, ensure_ascii=False), json.dumps([correct]), explanation))


def _append_legacy(course_id, title, count):
    missing = 12 - count
    if missing <= 0:
        return 0
    module_title = 'Практикум: закрепление навыка'
    module = one('SELECT id FROM modules WHERE course_id=? AND title=?', (course_id, module_title))
    if module:
        module_id = module['id']
    else:
        pos = one('SELECT COALESCE(MAX(position),-1)+1 n FROM modules WHERE course_id=?', (course_id,))['n']
        module_id = db().execute('INSERT INTO modules(course_id,title,position,description,outcomes) VALUES (?,?,?,?,?)',
                                 (course_id, module_title, pos,
                                  'Переносите материал курса на новые задачи и проверяйте результат.',
                                  'Объяснить решение, проверить границы и подготовить воспроизводимый результат.')).lastrowid
    additions = LEGACY_TOPICS.get(title, [])
    if len(additions) < missing:
        raise RuntimeError(f'Не хватает учебных тем для курса «{title}»: нужно ещё {missing}.')
    added = 0
    for item in additions:
        if added >= missing:
            break
        if one('SELECT id FROM lessons WHERE module_id=? AND title=?', (module_id, item[0])):
            continue
        pos = one('SELECT COALESCE(MAX(position),-1)+1 n FROM lessons WHERE module_id=?', (module_id,))['n']
        db().execute('INSERT INTO lessons(module_id,title,content,minutes,position) VALUES (?,?,?,?,?)',
                     (module_id, item[0], _lesson_html(title, item), 25, pos))
        added += 1
    if added != missing:
        raise RuntimeError(f'Не удалось добавить все недостающие темы курса «{title}».')
    return added


def fill_course_library():
    migrate()
    db().execute("UPDATE courses SET status='archived' WHERE status='published' AND (lower(trim(title))='новый курс' OR trim(title)='111111111111111')")
    created = 0
    added_lessons = 0
    for index, spec in enumerate(LIBRARY):
        course = one('SELECT id FROM courses WHERE title=?', (spec['title'],))
        if course:
            cid = course['id']
        else:
            db().execute('INSERT OR IGNORE INTO categories(name) VALUES (?)', (spec['category'],))
            cat = one('SELECT id FROM categories WHERE name=?', (spec['category'],))['id']
            cid = db().execute(
                "INSERT INTO courses(title,summary,description,outcomes,prerequisites,category_id,level,status,cover) VALUES (?,?,?,?,?,?,?,'published',?)",
                (spec['title'], spec['summary'], spec['description'], spec['outcomes'], spec['prerequisites'],
                 cat, spec['level'], f'/static/covers/{10+index}.svg')
            ).lastrowid
            created += 1
        current = one('SELECT count(*) n FROM lessons l JOIN modules m ON m.id=l.module_id WHERE m.course_id=?', (cid,))['n']
        if current >= 12:
            continue
        for module_pos, (module_title, description, topics, quiz) in enumerate(spec['modules']):
            module = one('SELECT id FROM modules WHERE course_id=? AND title=?', (cid, module_title))
            if module:
                module_id = module['id']
            else:
                module_id = db().execute(
                    'INSERT INTO modules(course_id,title,position,description,outcomes) VALUES (?,?,?,?,?)',
                    (cid, module_title, module_pos, description,
                     'Понять тему, применить её в упражнении и проверить результат.')
                ).lastrowid
            for lesson_pos, item in enumerate(topics):
                row = one('SELECT id FROM lessons WHERE module_id=? AND title=?', (module_id, item[0]))
                if row:
                    lesson_id = row['id']
                else:
                    pos = one('SELECT COALESCE(MAX(position),-1)+1 n FROM lessons WHERE module_id=?', (module_id,))['n']
                    lesson_id = db().execute(
                        'INSERT INTO lessons(module_id,title,content,minutes,position) VALUES (?,?,?,?,?)',
                        (module_id, item[0], _lesson_html(spec['title'], item), 20 + lesson_pos * 5, pos)
                    ).lastrowid
                    added_lessons += 1
                if lesson_pos == 3 and not one('SELECT id FROM quizzes WHERE lesson_id=?', (lesson_id,)):
                    _quiz(lesson_id, quiz)
        final = one('SELECT l.id FROM lessons l JOIN modules m ON m.id=l.module_id WHERE m.course_id=? ORDER BY m.position DESC,l.position DESC LIMIT 1', (cid,))
        if final and not one('SELECT id FROM assignments WHERE lesson_id=?', (final['id'],)):
            assignment_title, instructions, submission_type = spec['assignment']
            rubric = json.dumps([
                {'id': 'result', 'title': 'Результат отвечает условию и проверен', 'max_score': 60},
                {'id': 'reasoning', 'title': 'Решение объяснено, ограничения названы', 'max_score': 40},
            ], ensure_ascii=False)
            db().execute('INSERT INTO assignments(lesson_id,title,instructions,rubric,submission_type,max_score,required) VALUES (?,?,?,?,?,100,1)',
                         (final['id'], assignment_title, instructions, rubric, submission_type))

    published = rows("SELECT c.id,c.title,count(l.id) lessons FROM courses c LEFT JOIN modules m ON m.course_id=c.id LEFT JOIN lessons l ON l.module_id=m.id WHERE c.status='published' GROUP BY c.id ORDER BY c.id")
    for course in published:
        if course['lessons'] > 12:
            raise RuntimeError(f'Курс «{course["title"]}» уже содержит больше 12 уроков; его структура сохранена.')
        if course['lessons'] < 12:
            added_lessons += _append_legacy(course['id'], course['title'], course['lessons'])
    db().commit()
    result = rows("SELECT c.title,count(l.id) lessons FROM courses c LEFT JOIN modules m ON m.course_id=c.id LEFT JOIN lessons l ON l.module_id=m.id WHERE c.status='published' GROUP BY c.id ORDER BY c.id")
    return created, added_lessons, result


def register_course_library_command(app):
    @app.cli.command('fill-course-library')
    def fill_course_library_command():
        """Expand the published demo catalogue to 18 courses with 12 lessons each."""
        created, added, courses = fill_course_library()
        invalid = [f'{course["title"]} ({course["lessons"]})' for course in courses if course['lessons'] != 12]
        if invalid or len(courses) != 18:
            raise click.ClickException('Ожидались 18 опубликованных курсов по 12 уроков. Найдено: '
                                       + str(len(courses)) + '; ошибки: ' + ', '.join(invalid or ['неверное число курсов']))
        click.echo(f'Готово: 18 курсов по 12 уроков. Новых курсов: {created}; добавлено уроков: {added}.')
